Hermes Agent 中文聊天服务器
仿豆包/DeepSeek 风格的 Web 聊天界面后端
"""
import json, subprocess, os, sys, time, uuid, threading
from pathlib import Path

try:
    from fastapi import FastAPI, Request
    from fastapi.responses import HTMLResponse, JSONResponse, StreamingResponse
    import uvicorn
except ImportError:
    print("需要 fastapi 和 uvicorn，正在安装...")
