    from fastapi import FastAPI, Request
    from fastapi.responses import HTMLResponse, JSONResponse
    import uvicorn

app = FastAPI(title="Hermes Chat", docs_url=None, redoc_url=None)

SESSIONS_DIR = Path.home() / ".hermes" / "chat_sessions"
SESSIONS_DIR.mkdir(parents=True, exist_ok=True)
CURRENT_SESSION_FILE = SESSIONS_DIR / "current_session.json"

HTML_PATH = Path("/mnt/c/Users/Administrator/Desktop/hermes_chat.html")

# ========== Helper ==========

def get_current_session():
    if CURRENT_SESSION_FILE.exists():
        return json.loads(CURRENT_SESSION_FILE.read_text())
    return None

def save_current_session(session_id):
    CURRENT_SESSION_FILE.write_text(json.dumps({"session_id": session_id, "created": time.time()}))

def run_hermes(query: str, session_id: str = None, image_path: str = None) -> dict:
    """Run hermes chat -q and return the response"""
    cmd = ["hermes", "chat", "-q", query]

    if session_id:
        cmd.extend(["--resume", session_id])

    if image_path:
        cmd.extend(["--image", image_path])

    try:
        env = os.environ.copy()
        env["HERMES_DISPLAY_COMPACT"] = "true"
        env["NO_COLOR"] = "1"

        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            timeout=300,
            env=env,
            cwd=str(Path.home())
        )

        output = result.stdout.strip()
        error = result.stderr.strip()

        # Extract session ID from stderr or stdout
        new_session_id = session_id
        for line in (result.stderr + result.stdout).split("\n"):
            if "session" in line.lower() and "id" in line.lower():
                import re
                match = re.search(r'[a-f0-9]{8}', line)
                if match:
                    new_session_id = match.group(0)

        return {
            "success": result.returncode == 0,
            "response": output,
            "error": error if error and not output else None,
            "session_id": new_session_id
        }
    except subprocess.TimeoutExpired:
        return {"success": False, "response": "", "error": "请求超时（5分钟）"}
    except Exception as e:
        return {"success": False, "response": "", "error": str(e)}


# ========== API Routes ==========

@app.post("/api/chat")
async def chat(request: Request):
    data = await request.json()
    query = data.get("message", "").strip()
    session_id = data.get("session_id")

    if not query:
        return JSONResponse({"success": False, "error": "消息不能为空"}, status_code=400)

    # Auto-resume last session if available
    if not session_id:
        sess = get_current_session()
        if sess:
            session_id = sess["session_id"]

    result = run_hermes(query, session_id)

    if result["success"] and result["session_id"]:
        save_current_session(result["session_id"])

    return JSONResponse(result)


@app.post("/api/new-session")
async def new_session():
    """Start a new chat session"""
    CURRENT_SESSION_FILE.unlink(missing_ok=True)
    return JSONResponse({"success": True, "message": "新会话已开始"})


@app.get("/api/status")
async def status():
    sess = get_current_session()
    return JSONResponse({
        "connected": True,
        "session": sess,
        "model": "deepseek-v4-pro"
    })


@app.get("/")
async def index():
    """Serve the chat HTML"""
    if HTML_PATH.exists():
        return HTMLResponse(HTML_PATH.read_text(encoding="utf-8"))
    return HTMLResponse("<h2>HTML 文件未找到，请先创建桌面上的 hermes_chat.html</h2>")


if __name__ == "__main__":
