<script>
// ============ 状态 ============
let sessionId = null;
let isLoading = false;
let theme = localStorage.getItem('hermes-theme') || 'dark';

// ============ 主题 ============
const themeClasses = {
  dark: '', pink: 'theme-pink', gold: 'theme-gold', 
  green: 'theme-green', ocean: 'theme-ocean', light: 'theme-light'
};

function setTheme(name) {
  theme = name;
  localStorage.setItem('hermes-theme', name);
  document.body.className = themeClasses[name] || '';
  document.getElementById('themePicker').classList.remove('show');
  updateActiveDot();
}

function toggleThemePicker() {
  document.getElementById('themePicker').classList.toggle('show');
}

function updateActiveDot() {
  document.querySelectorAll('.theme-dot').forEach(d => d.classList.remove('active'));
  const idx = Object.keys(themeClasses).indexOf(theme);
  if (idx >= 0) document.querySelectorAll('.theme-dot')[idx]?.classList.add('active');
}

// 初始化主题
document.body.className = themeClasses[theme] || '';
updateActiveDot();
// 点击外部关闭主题选择器
document.addEventListener('click', e => {
  if (!e.target.closest('.theme-picker') && !e.target.closest('.header-btn')) {
    document.getElementById('themePicker').classList.remove('show');
  }
});

// ============ 消息 ============
function addMessage(role, content, loading = false) {
  const chatArea = document.getElementById('chatArea');
  const emptyState = document.getElementById('emptyState');
  if (emptyState) emptyState.remove();

  const div = document.createElement('div');
  div.className = `message ${role}`;

  const avatar = role === 'user' ? '👤' : '🤖';
  const avatarBg = role === 'user' ? 'var(--accent)' : 'var(--accent2)';

  div.innerHTML = `
    <div class="avatar">${avatar}</div>
    <div class="bubble${loading ? ' loading' : ''}">${escapeHtml(content)}${loading ? '<span class="dot-pulse"></span>' : ''}</div>
  `;

  chatArea.appendChild(div);
  chatArea.scrollTop = chatArea.scrollHeight;
  return div;
}

function escapeHtml(text) {
  const div = document.createElement('div');
  div.textContent = text;
  return div.innerHTML;
}

// ============ 发送 ============
async function sendMessage() {
  const input = document.getElementById('userInput');
  const msg = input.value.trim();
  if (!msg || isLoading) return;

  isLoading = true;
  input.value = '';
  input.style.height = 'auto';
  document.getElementById('sendBtn').disabled = true;
  document.getElementById('sendBtn').classList.add('loading');
  document.getElementById('sendBtn').textContent = '…';

  // 添加用户消息
  addMessage('user', msg);

  // 添加加载中的 AI 消息
  const loadingDiv = addMessage('ai', '', true);

  try {
    const resp = await fetch('/api/chat', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ message: msg, session_id: sessionId })
    });

    const data = await resp.json();

    // 移除加载指示
    loadingDiv.remove();

    if (data.success) {
      if (data.session_id) sessionId = data.session_id;
      addMessage('ai', data.response || '(无响应)');
    } else {
      addMessage('ai', '❌ 出错了：' + (data.error || '未知错误'));
    }
  } catch (e) {
    loadingDiv.remove();
    addMessage('ai', '❌ 网络错误：' + e.message);
  }

  isLoading = false;
  document.getElementById('sendBtn').disabled = false;
  document.getElementById('sendBtn').classList.remove('loading');
  document.getElementById('sendBtn').textContent = '▶';
  input.focus();
}

function sendQuick(el) {
  document.getElementById('userInput').value = el.textContent;
  sendMessage();
}

function handleKey(e) {
  if (e.key === 'Enter' && !e.shiftKey) {
    e.preventDefault();
    sendMessage();
  }
  // 自动调整高度
  setTimeout(() => {
    const ta = e.target;
    ta.style.height = 'auto';
    ta.style.height = Math.min(ta.scrollHeight, 120) + 'px';
  }, 0);
}

// ============ 新会话 ============
async function newSession() {
  if (isLoading) return;
  try {
    await fetch('/api/new-session', { method: 'POST' });
  } catch(e) {}
  sessionId = null;
  const chatArea = document.getElementById('chatArea');
  chatArea.innerHTML = `
    <div class="empty-state" id="emptyState">
      <div class="icon">🤖</div>
      <h2>新对话已开始</h2>
      <p>有什么可以帮你的？</p>
      <div class="quick-prompts">
        <span class="quick-prompt" onclick="sendQuick(this)">写一个 Python 排序函数</span>
        <span class="quick-prompt" onclick="sendQuick(this)">解释一下量子计算</span>
        <span class="quick-prompt" onclick="sendQuick(this)">帮我写一段文案</span>
        <span class="quick-prompt" onclick="sendQuick(this)">今天有什么新闻</span>
      </div>
    </div>
  `;
}

// 初始化
document.getElementById('userInput').focus();
</script>
